use super::*;
use crate::store::dv_refit_jobs::PublishRefitJob;
use crate::transcode::dv_refit::RefitStats;

/// A real helper run over the Michael5400 window: the milestone 2 helper's
/// output, regenerated byte for byte (apart from the `rpu_scene_frames` it
/// now adds) by the resumable helper.
const RECORDED: &str = include_str!("../../tests/fixtures/dv-refit/helper-run-michael5400.jsonl");

/// The curve digest of [`RECORDED`]. Two separate real helper runs over the
/// same window print this; a change here is a change to the served curves.
const RECORDED_DIGEST: &str = "2a8d78f7cf05fff325afe70c4f5ce2d1972317027cd0bdb045202d16310cb75b";

/// Samples of a scene whose composition is the identity mapping of the base
/// layer moved by `offset` codes, with ±`noise` alternating around it, and
/// chroma passed through. `phase` varies the chroma so fit and held-out
/// samples differ.
pub(super) fn stats(offset: i32, noise: i32, phase: u32) -> RefitStats {
    let mut stats = RefitStats::new();
    for i in 0..4000u32 {
        let y = 64 + (i * 7 + phase) % 896;
        let u = 256 + (i * 37 + phase * 3) % 512;
        let v = 256 + (i * 91 + phase * 5) % 512;
        let sign = if i % 2 == 0 { 1 } else { -1 };
        let composed = (4 * y as i32 + offset + sign * noise).clamp(0, 4095) as u16;
        stats.add(
            [y as u16, u as u16, v as u16],
            [composed, (4 * u) as u16, (4 * v) as u16],
        );
    }
    stats
}

/// A run in the helper's contract: scenes of (frames, fit, held-out), each
/// pooled from RPU scenes of `rpu_scene` frames (the last one takes the
/// remainder), then the summary an uninterrupted run writes.
pub(super) fn output(scenes: &[(u64, RefitStats, RefitStats)], rpu_scene: u64) -> String {
    let mut lines = Vec::new();
    let mut parsed = Vec::new();
    let mut frame = 0u64;
    let pts = |frame: u64| 125 + frame as i64 * 42;
    for (frames, fit, held) in scenes {
        let mut lengths = vec![rpu_scene; (*frames / rpu_scene).max(1) as usize];
        *lengths.last_mut().expect("one") += frames - lengths.iter().sum::<u64>();
        let line = serde_json::json!({"kind":"refit_scene","first_frame":frame,"frames":frames,
            "first_pts":pts(frame),"end_pts":pts(frame + frames) - 1,"time_base":"1/1000",
            "rpu_scene_frames":lengths,"fit":fit,"held_out":held})
        .to_string();
        parsed.push(RefitScene::from_line(&line).expect("scene"));
        lines.push(line);
        frame += frames;
    }
    let summary = summarise(&parsed).expect("summary");
    lines.push(serde_json::to_string(&summary).expect("summary"));
    lines.join("\n") + "\n"
}

/// Two scenes the fit helps (offsets 12 and −10 codes), one whose held-out
/// samples are the identity mapping (so its fit does worse there).
fn mixed() -> String {
    output(
        &[
            (48, stats(12, 0, 0), stats(12, 0, 1)),
            (96, stats(-10, 0, 2), stats(-10, 0, 3)),
            (72, stats(30, 0, 4), stats(0, 0, 5)),
        ],
        48,
    )
}

fn source() -> RefitSource {
    RefitSource {
        file_id: 7,
        source_size: 100,
        source_mtime: 5,
        video_index: 0,
        probe_revision: 3,
        helper_identity: "a".repeat(64),
    }
}

fn token() -> crate::store::background_jobs::JobToken {
    serde_json::from_value(
        serde_json::json!({"job_id":uuid::Uuid::new_v4().to_string(),
        "node_id":"n","boot_id":uuid::Uuid::new_v4().to_string(),
        "claim_id":uuid::Uuid::new_v4().to_string(),"fence":1,"revision":1,"lease_expires_ms":1}),
    )
    .expect("token")
}

fn publication(title: &TitleFit) -> PublishRefitJob {
    let (title, scenes) = title.rows(&source()).expect("rows");
    PublishRefitJob {
        token: token(),
        title,
        scenes,
        now_ms: 1,
    }
}

#[test]
fn the_recorded_helper_run_parses_and_fits() {
    let out = parse(RECORDED.as_bytes()).expect("the recorded run");
    assert_eq!(out.scenes.len(), 5);
    assert_eq!(out.summary.frames, 311);
    let title = fit(out);
    assert_eq!(title.verdict, RefitVerdict::Fitted, "{:?}", title.reason);
    assert!(
        title.gain.is_some_and(|g| g > MIN_TITLE_GAIN),
        "{:?}",
        title.gain
    );
    let publish = publication(&title);
    publish.check().expect("one valid publication");
    assert_eq!(
        (
            publish.scenes[0].first_pts,
            publish.scenes[0].end_pts,
            publish.scenes[1].first_pts
        ),
        (125, 2252, 2253)
    );
    let again = fit(parse(RECORDED.as_bytes()).expect("again"));
    assert_eq!(again.curve_digest, title.curve_digest, "stable across runs");
    assert_eq!(
        title.curve_digest, RECORDED_DIGEST,
        "the served curves moved"
    );
}

/// Decision K: two real helper runs over Michael5400's source window give
/// the same digest. Run by `tools/dv_processing/controls/refit_digest_twice.sh`,
/// which runs the helper twice and points these at the two outputs.
#[test]
#[ignore = "needs two real helper runs (PLURX_REFIT_RUN_A, PLURX_REFIT_RUN_B)"]
fn two_real_helper_runs_give_the_same_digest() {
    let digest = |var: &str| {
        let path = std::env::var(var).expect(var);
        let bytes = std::fs::read(&path).expect("helper output");
        let title = fit(parse(&bytes).expect("a complete run"));
        publication(&title).check().expect("publishable");
        title.curve_digest
    };
    let (a, b) = (digest("PLURX_REFIT_RUN_A"), digest("PLURX_REFIT_RUN_B"));
    assert_eq!(a, b, "two runs disagree");
    assert_eq!(
        a, RECORDED_DIGEST,
        "the runs disagree with the recorded run"
    );
}

#[test]
fn a_mixed_title_serves_the_scenes_that_pass() {
    let title = fit(parse(mixed().as_bytes()).expect("contract"));
    assert_eq!(title.verdict, RefitVerdict::Fitted, "{:?}", title.reason);
    let solved: Vec<bool> = title.scenes.iter().map(|s| s.served.is_some()).collect();
    assert_eq!(solved, [true, true, false]);
    assert!(title.scenes[2]
        .reason
        .as_deref()
        .is_some_and(|r| r.contains("worse than identity")));
    assert!(title.gain.is_some_and(|g| g > MIN_TITLE_GAIN && g < 1.0));
    let publish = publication(&title);
    publish.check().expect("valid");
    assert_eq!(publish.title.scene_count, 3);
    let served = &publish.scenes[0];
    assert!(served.gain.is_some_and(|g| g > 0.0) && served.fitted_error.is_some());
    assert!(publish.scenes[2].fitted_error.is_none() && publish.scenes[2].reason.is_some());
}

#[test]
fn stored_coefficients_are_what_the_composer_writes() {
    let title = fit(parse(RECORDED.as_bytes()).expect("contract"));
    for scene in &title.scenes {
        let (Some(curves), Some(q)) = (&scene.curves, &scene.served) else {
            continue;
        };
        let servable = servable(curves).expect("served curves are servable");
        assert_eq!(&servable.quantised(), q);
        let loaded = ServableCurves::from_quantised(q).expect("loads");
        assert_eq!(&loaded.quantised(), q, "n / 2^23 is exact");
    }
}

#[test]
fn a_degenerate_title_serves_identity_everywhere() {
    let text = output(&[(48, stats(12, 0, 0), stats(12, 0, 1))], 12);
    let title = fit(parse(text.as_bytes()).expect("contract"));
    assert_eq!(title.verdict, RefitVerdict::Identity);
    assert!(title
        .reason
        .as_deref()
        .is_some_and(|r| r.contains("scene_refresh_flag")));
    let first = &title.scenes[0].scene;
    assert!(title.scenes.iter().all(|s| s.served.is_none()));
    assert_eq!(
        title.curve_digest,
        curve_digest([DigestScene {
            first_frame: 0,
            frames: first.frames,
            first_pts: first.first_pts,
            end_pts: first.end_pts,
            time_base: &first.time_base,
            coefficients: None,
        }])
    );
    publication(&title).check().expect("valid");
}

#[test]
fn a_title_under_five_percent_keeps_identity() {
    // Offset 2 under ±20 noise: the fit removes 4 of 404 codes² per sample.
    let text = output(
        &[
            (48, stats(2, 20, 0), stats(2, 20, 1)),
            (48, stats(2, 20, 2), stats(2, 20, 3)),
        ],
        48,
    );
    let title = fit(parse(text.as_bytes()).expect("contract"));
    assert!(
        title.scenes.iter().all(|s| s.curves.is_some()),
        "scenes pass alone"
    );
    assert_eq!(title.verdict, RefitVerdict::Identity);
    let gain = title.gain.expect("measured");
    assert!(gain > 0.0 && gain < MIN_TITLE_GAIN, "{gain}");
    assert!(title.reason.as_deref().is_some_and(|r| r.contains("floor")));
    assert!(
        title.scenes.iter().all(|s| s.served.is_none()),
        "an identity title serves no curves"
    );
    publication(&title).check().expect("valid");
}

#[test]
fn the_digest_is_stable_and_names_the_curves() {
    let first = fit(parse(mixed().as_bytes()).expect("first"));
    let second = fit(parse(mixed().as_bytes()).expect("second"));
    assert_eq!(first, second);
    let other = output(
        &[
            (48, stats(13, 0, 0), stats(13, 0, 1)),
            (96, stats(-10, 0, 2), stats(-10, 0, 3)),
            (72, stats(30, 0, 4), stats(0, 0, 5)),
        ],
        48,
    );
    assert_ne!(
        fit(parse(other.as_bytes()).expect("other")).curve_digest,
        first.curve_digest
    );
    assert_ne!(first.curve_digest, empty_digest());
    // The digest is over the stored integers: rows whose coefficients
    // change by one numerator fail the publication's own check.
    let mut publish = publication(&first);
    publish.scenes[0]
        .coefficients
        .as_mut()
        .expect("served")
        .luma[0][0] += 1;
    assert!(publish.check().is_err());
}

#[test]
fn publication_refuses_rows_that_disagree() {
    let title = fit(parse(mixed().as_bytes()).expect("contract"));
    let mut gap = publication(&title);
    gap.scenes[1].first_frame += 1;
    assert!(gap.check().is_err(), "a gap between scenes");
    let mut short = publication(&title);
    short.scenes.pop();
    assert!(short.check().is_err(), "a missing scene");
    let mut identity = publication(&title);
    identity.title.verdict = RefitVerdict::Identity;
    identity.title.reason = Some("x".into());
    assert!(identity.check().is_err(), "an identity title with curves");
    let mut nan = publication(&title);
    nan.scenes[0].identity_error = f64::NAN;
    assert!(nan.check().is_err(), "a non-finite error number");
}

#[test]
fn malformed_or_truncated_helper_output_is_refused() {
    let good = mixed();
    let lines: Vec<&str> = good.trim_end().split('\n').collect();
    let joined = |lines: &[&str]| lines.join("\n");
    assert!(parse(joined(&lines[..3]).as_bytes())
        .expect_err("refused")
        .contains("truncated"));
    assert!(parse(&good.as_bytes()[..good.len() / 2]).is_err());
    let recorded: Vec<&str> = RECORDED.trim_end().split('\n').collect();
    assert!(
        parse(joined(&recorded[..5]).as_bytes()).is_err(),
        "no summary"
    );
    // A scene after the summary, a missing scene, counts that disagree.
    let mut late = lines.clone();
    late.push(lines[0]);
    assert!(parse(joined(&late).as_bytes()).is_err());
    assert!(parse(joined(&[lines[0], lines[2], lines[3]]).as_bytes()).is_err());
    let mut value: serde_json::Value = serde_json::from_str(lines[3]).expect("summary");
    value["fit_samples"] = (value["fit_samples"].as_u64().expect("count") + 1).into();
    let wrong = value.to_string();
    assert!(parse(joined(&[lines[0], lines[1], lines[2], &wrong]).as_bytes()).is_err());
    // Statistics of the wrong shape, an unknown kind or field, a bad time base.
    let mut scene: serde_json::Value = serde_json::from_str(lines[0]).expect("scene");
    scene["fit"]["ysum"] = serde_json::json!([1.0, 2.0]);
    let shape = scene.to_string();
    assert!(parse(joined(&[&shape, lines[1], lines[2], lines[3]]).as_bytes()).is_err());
    let kind = lines[0].replace("refit_scene", "refit_frame");
    assert!(parse(joined(&[&kind, lines[1], lines[2], lines[3]]).as_bytes()).is_err());
    let extra = lines[3].replace("\"degenerate\":false", "\"degenerate\":false,\"extra\":1");
    assert!(parse(joined(&[lines[0], lines[1], lines[2], &extra]).as_bytes()).is_err());
    // RPU scene lengths that do not sum to the scene's frames.
    let mut lengths: serde_json::Value = serde_json::from_str(lines[0]).expect("scene");
    lengths["rpu_scene_frames"] = serde_json::json!([47]);
    let lengths = lengths.to_string();
    assert!(parse(joined(&[&lengths, lines[1], lines[2], lines[3]]).as_bytes()).is_err());
    assert!(parse(b"").is_err());
}

/// Decision F: resuming at any kept scene's start and joining the resumed
/// run to the scenes before it gives the uninterrupted run, summary
/// included. The helper's own control (`test_refit_resume.py`) shows the
/// resumed scene lines equal the uninterrupted run's on the real clip.
#[test]
fn a_resumed_run_joins_to_the_uninterrupted_one() {
    let whole = parse(RECORDED.as_bytes()).expect("whole");
    let lines: Vec<&str> = RECORDED.trim_end().split('\n').collect();
    for torn in 2..=lines.len() - 1 {
        // An interruption after `torn` whole scene lines and half a line.
        let mut partial = lines[..torn].join("\n") + "\n";
        partial.push_str(&lines[torn][..lines[torn].len() / 2]);
        let kept = complete_scenes(partial.as_bytes());
        assert_eq!(kept.len(), torn);
        assert!(kept
            .iter()
            .zip(&lines)
            .all(|((line, _), want)| line == want));
        let scenes: Vec<RefitScene> = kept.iter().map(|(_, s)| s.clone()).collect();
        let (keep, at) = resume_point(&scenes).expect("resumable");
        assert_eq!(keep, torn - 1);
        // The resumed run: the scenes from `at` on and a summary of only them.
        let resumed_scenes = &whole.scenes[keep..];
        assert_eq!(resumed_scenes[0].first_frame, at.first_frame);
        let mut resumed = lines[keep..lines.len() - 1].join("\n");
        resumed.push('\n');
        resumed.push_str(
            &serde_json::to_string(&summarise(resumed_scenes).expect("tail")).expect("json"),
        );
        let joined =
            parse_resumed(scenes[..keep].to_vec(), at, resumed.as_bytes()).expect("joined");
        assert_eq!(joined, whole, "resumed at scene {keep}");
        assert_eq!(fit(joined).curve_digest, RECORDED_DIGEST);
        // The spool text of the joined run parses as the whole run.
        let scene_lines: Vec<String> = lines[..lines.len() - 1]
            .iter()
            .map(|l| (*l).to_owned())
            .collect();
        let spool = spool_text(&scene_lines, &whole.summary).expect("spool");
        assert_eq!(parse(spool.as_bytes()).expect("spool parses"), whole);
        // A resumed run that starts anywhere else is refused.
        let wrong = ResumePoint {
            first_frame: at.first_frame,
            first_pts: at.first_pts + 1,
        };
        assert!(parse_resumed(scenes[..keep].to_vec(), wrong, resumed.as_bytes()).is_err());
    }
    assert!(complete_scenes(b"").is_empty());
    assert!(
        resume_point(&whole.scenes[..1]).is_none(),
        "nothing to keep: start over"
    );
    // A summary or a foreign line ends the kept prefix.
    assert_eq!(complete_scenes(RECORDED.as_bytes()).len(), 5);
}

#[test]
fn a_refusal_row_is_valid_and_bounded() {
    let row = refusal(
        &source(),
        &format!(
            "Segment refused: full-resolution enhancement layer\n{}",
            "x".repeat(4000)
        ),
    );
    assert!(row.valid());
    assert_eq!(row.verdict, RefitVerdict::Refused);
    assert_eq!(row.curve_digest, empty_digest());
    let reason = row.reason.as_deref().expect("reason");
    assert!(!reason.contains('\n') && reason.starts_with("full-resolution"));
    PublishRefitJob {
        token: token(),
        title: row,
        scenes: Vec::new(),
        now_ms: 1,
    }
    .check()
    .expect("a refusal publishes");
}
